"""Adversarial Intelligence Subsystem contracts."""

from dataclasses import dataclass, field
from typing import Dict, Any, List, Optional


@dataclass
class AdversarialAttackReport:
    """Report generated by the independent Adversarial Subsystem attacking a trade setup."""
    hypothesis_id: str
    vulnerabilities_found: List[str]
    contradictory_evidence: List[str]
    regime_destructors: List[str]
    overfitting_risk_level: str  # LOW, MEDIUM, HIGH, CRITICAL
    execution_erosion_pips: float
    attack_passed: bool
    confidence_penalty: float = 0.0
    metadata: Dict[str, Any] = field(default_factory=dict)
